(* [comment removed for export] *)
Lemma srai48_run (fx : FPState) R M (pc : Z) (W : bv 32) (rd rs : bv 5) :
  fetch_word RSEGS (Z_to_bv 64 pc) = Some W -> is_ecall W = false -> decode_any W = Some (ShiftImm ALU_SRA rd rs 48, 4%Z) ->
  rd <> 0%bv -> 0 <= pc -> pc + 4 < 2 ^ 64 ->
  exists x v, - 2 ^ 15 <= x < 2 ^ 15 /\ v = x mod 2 ^ 64 /\ 0 <= v < 2 ^ 64 /\ PQVA.sval v = x
    /\ msteps RSEGS (st fx R pc M) (st fx (regupd R rd (Z_to_bv 64 v)) (pc + 4) M).
